package com.nigson.experience.files;

import com.nimbusds.jose.*;import com.nimbusds.jose.crypto.*;import com.nimbusds.jose.jwk.*;import com.nimbusds.jwt.*;import com.nigson.experience.ExperienceApplication;import com.nigson.shared.events.EventCodec;import com.nigson.shared.security.*;import com.sun.net.httpserver.HttpServer;import java.net.*;import java.net.http.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.security.interfaces.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import org.springframework.boot.builder.SpringApplicationBuilder;import org.springframework.boot.web.server.context.WebServerApplicationContext;import org.springframework.jdbc.core.JdbcTemplate;import static org.assertj.core.api.Assertions.*;
class ExperienceFileHttpTest {
 @Test void actualHttpAndPostgresEnforceQuarantineOwnershipReplayStaleAndUnknownReconciliation()throws Exception{
  String db=System.getenv("NIGSON_TEST_JDBC_URL");Assumptions.assumeTrue(db!=null,"EXP-FILES-001 uses isolated native PostgreSQL");var rg=KeyPairGenerator.getInstance("RSA");rg.initialize(2048);var rsa=rg.generateKeyPair();var eg=KeyPairGenerator.getInstance("EC");eg.initialize(new java.security.spec.ECGenParameterSpec("secp256r1"));var ec=eg.generateKeyPair();var jwks=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);String issuer="http://127.0.0.1:"+jwks.getAddress().getPort()+"/realms/offline";jwks.createContext("/",x->{byte[] b=EventCodec.JSON.writeValueAsBytes(Map.of("keys",List.of(new com.nimbusds.jose.jwk.RSAKey.Builder((RSAPublicKey)rsa.getPublic()).keyID("synthetic").algorithm(JWSAlgorithm.RS256).keyUse(KeyUse.SIGNATURE).build().toJSONObject())));x.getResponseHeaders().set("Content-Type","application/json");x.sendResponseHeaders(200,b.length);x.getResponseBody().write(b);x.close();});jwks.start();
  var props=new HashMap<String,Object>();props.put("APP_ENV","test");props.put("NIGSON_SECURITY_ENABLED","true");props.put("NIGSON_PRODUCT_PHASE","3");props.put("NIGSON_EVENTS_ENABLED","false");props.put("NIGSON_JDBC_URL",db+"?currentSchema=experience");props.put("NIGSON_DB_USER","nigson_experience_app");props.put("NIGSON_DB_PASSWORD","mock-experience-runtime");props.put("NIGSON_OIDC_ISSUER",issuer);props.put("NIGSON_OIDC_JWKS",issuer+"/protocol/openid-connect/certs");props.put("NIGSON_PRIVATE_PEER_CIDRS","127.0.0.1/32");props.put("NIGSON_ACTOR_PUBLIC_KEYS",EventCodec.JSON.writeValueAsString(Map.of("active",Base64.getEncoder().encodeToString(ec.getPublic().getEncoded()))));props.put("NIGSON_DISTRIBUTOR_REQUIRED_DOCUMENT_TYPES","CERTIFICATE,IDENTITY");props.put("NIGSON_DISTRIBUTOR_RECIPIENT_GROUP","synthetic-review-group");props.put("NIGSON_DISTRIBUTOR_COMMERCE_MODE","mock");props.put("NIGSON_FILES_ENABLED","true");props.put("NIGSON_FILES_MOCK","true");props.put("NIGSON_FILES_SCAN_ENABLED","true");props.put("NIGSON_MESSAGING_INBOUND_ENABLED","true");props.put("NIGSON_PHONE_CIPHER_REVISION","synthetic");props.put("NIGSON_PHONE_HASH_KEY_VERSION","1");byte[] ph=new byte[32],pc=new byte[32],ic=new byte[32];Arrays.fill(ph,(byte)7);Arrays.fill(pc,(byte)8);Arrays.fill(ic,(byte)9);props.put("NIGSON_PHONE_LOCAL_HASH_KEY",Base64.getEncoder().encodeToString(ph));props.put("NIGSON_PHONE_LOCAL_CIPHER_KEY",Base64.getEncoder().encodeToString(pc));props.put("NIGSON_INBOUND_LOCAL_CIPHER_KEY",Base64.getEncoder().encodeToString(ic));props.put("NIGSON_INBOUND_RETENTION_DAYS","30");props.put("NIGSON_TWILIO_ACCOUNT_SID","AC0123456789abcdef0123456789abcdef");props.put("NIGSON_TWILIO_AUTH_TOKEN","synthetic-twilio-auth-never-live");props.put("NIGSON_TWILIO_WHATSAPP_FROM","whatsapp:+2348031234567");props.put("NIGSON_TWILIO_WHATSAPP_PUBLIC_URL","https://callbacks.synthetic.invalid/api/v1/webhooks/notifications/twilio/whatsapp");props.put("server.port","0");props.put("logging.level.root","WARN");
  try(var app=new SpringApplicationBuilder(ExperienceApplication.class).properties(props).run();var http=HttpClient.newHttpClient()){String base="http://127.0.0.1:"+((WebServerApplicationContext)app).getWebServer().getPort();var jdbc=app.getBean(JdbcTemplate.class);var storage=(StatefulFileStorageMock)app.getBean(FileStorage.class);UUID customer=UUID.randomUUID(),other=UUID.randomUUID();String checksum="a".repeat(64),uploadPath="/api/v1/experience/files/uploads",uploadBody=EventCodec.JSON.writeValueAsString(Map.of("purpose","DISTRIBUTOR_PROOF","filename","proof.pdf","mimeType","application/pdf","size",2048,"checksumSha256",checksum));String uploadKey=UUID.randomUUID().toString();var created=actorCall(http,base,rsa,ec,issuer,"POST",uploadPath,"files.upload_WITH_SIGNED_ACTOR","CUSTOMER",uploadBody,uploadKey,null,customer);assertThat(created.statusCode()).withFailMessage(created.body()).isEqualTo(201);assertThat(created.headers().firstValue("Cache-Control")).contains("no-store");assertThat(actorCall(http,base,rsa,ec,issuer,"POST",uploadPath,"files.upload_WITH_SIGNED_ACTOR","CUSTOMER",uploadBody,uploadKey,null,customer).body()).isEqualTo(created.body());UUID asset=UUID.fromString(EventCodec.JSON.readTree(created.body()).path("assetId").asString());assertThat(jdbc.queryForObject("SELECT scan_status FROM experience.file_asset WHERE id=?",String.class,asset)).isEqualTo("UPLOADING");
   String completePath="/api/v1/experience/files/"+asset+"/completion",completeBody="{\"checksumSha256\":\""+checksum+"\"}";var denied=actorCall(http,base,rsa,ec,issuer,"POST",completePath,"files.complete_WITH_SIGNED_ACTOR","CUSTOMER",completeBody,UUID.randomUUID().toString(),"\"0\"",other);assertThat(denied.statusCode()).isEqualTo(403);assertThat(jdbc.queryForObject("SELECT scan_status FROM experience.file_asset WHERE id=?",String.class,asset)).isEqualTo("UPLOADING");String completeKey=UUID.randomUUID().toString();var stale=actorCall(http,base,rsa,ec,issuer,"POST",completePath,"files.complete_WITH_SIGNED_ACTOR","CUSTOMER",completeBody,completeKey,"\"2\"",customer);assertThat(stale.statusCode()).isEqualTo(412);var completed=actorCall(http,base,rsa,ec,issuer,"POST",completePath,"files.complete_WITH_SIGNED_ACTOR","CUSTOMER",completeBody,completeKey,"\"0\"",customer);assertThat(completed.statusCode()).withFailMessage(completed.body()).isEqualTo(202);assertThat(completed.headers().firstValue("ETag")).contains("\"1\"");assertThat(actorCall(http,base,rsa,ec,issuer,"POST",completePath,"files.complete_WITH_SIGNED_ACTOR","CUSTOMER",completeBody,completeKey,"\"0\"",customer).body()).isEqualTo(completed.body());String downloadPath="/api/v1/experience/files/"+asset+"/download";assertThat(actorCall(http,base,rsa,ec,issuer,"GET",downloadPath,"files.download_WITH_SIGNED_ACTOR","CUSTOMER","",null,null,customer).statusCode()).isEqualTo(409);assertThat(actorCall(http,base,rsa,ec,issuer,"GET",downloadPath,"files.download_WITH_SIGNED_ACTOR","CUSTOMER","",null,null,other).statusCode()).isEqualTo(403);
   UUID command=jdbc.queryForObject("SELECT scan_command_id FROM experience.file_transfer WHERE id=?",UUID.class,asset);String scanPath="/internal/v1/files/"+asset+"/scan-result",scanBody=EventCodec.JSON.writeValueAsString(Map.of("commandId",command,"checksumSha256",checksum,"result","CLEAN","scannerVersion","mock-1"));String event=jdbc.queryForObject("SELECT payload::text FROM experience.outbox_event WHERE aggregate_id=? AND event_type='file.scan.requested.v1'",String.class,asset);assertThat(EventCodec.decode(event).path("payload").path("owner_service").asString()).isEqualTo("experience");assertThat(EventCodec.decode(event).path("event_id").asString()).isEqualTo(command.toString());String scanner=workload(rsa,issuer,"nigson-integration","files.scan.write");var wrongVersion=privateCall(http,base+scanPath,"POST",scanBody,scanner,command.toString(),"\"0\"");assertThat(wrongVersion.statusCode()).isEqualTo(412);String scanKey=command.toString();storage.failCopyAfterAcceptance();var unknown=privateCall(http,base+scanPath,"POST",scanBody,scanner,scanKey,"\"1\"");assertThat(unknown.statusCode()).isEqualTo(503);assertThat(jdbc.queryForObject("SELECT state FROM experience.file_transfer WHERE id=?",String.class,asset)).isEqualTo("UNKNOWN");assertThat(jdbc.queryForObject("SELECT scan_status FROM experience.file_asset WHERE id=?",String.class,asset)).isEqualTo("QUARANTINED");var clean=privateCall(http,base+scanPath,"POST",scanBody,scanner,scanKey,"\"1\"");assertThat(clean.statusCode()).withFailMessage(clean.body()).isEqualTo(200);assertThat(EventCodec.JSON.readTree(clean.body()).path("state").asString()).isEqualTo("CLEAN");assertThat(privateCall(http,base+scanPath,"POST",scanBody,scanner,scanKey,"\"1\"").body()).isEqualTo(clean.body());assertThat(jdbc.queryForObject("SELECT scan_status FROM experience.file_asset WHERE id=?",String.class,asset)).isEqualTo("CLEAN");var downloaded=actorCall(http,base,rsa,ec,issuer,"GET",downloadPath,"files.download_WITH_SIGNED_ACTOR","CUSTOMER","",null,null,customer);assertThat(downloaded.statusCode()).withFailMessage(downloaded.body()).isEqualTo(200);assertThat(EventCodec.JSON.readTree(downloaded.body()).path("url").asString()).startsWith("https://s3-mock.invalid/");assertThat(actorCall(http,base,rsa,ec,issuer,"GET",downloadPath,"files.download_WITH_SIGNED_ACTOR","CUSTOMER","",null,null,other).statusCode()).isEqualTo(403);
  }finally{jwks.stop(0);}
 }
 private static String workload(KeyPair rsa,String issuer,String client,String scope)throws Exception{var j=new SignedJWT(new JWSHeader.Builder(JWSAlgorithm.RS256).keyID("synthetic").build(),new JWTClaimsSet.Builder().issuer(issuer).subject("synthetic-workload").audience("nigson-experience").claim("client_id",client).claim("azp",client).claim("scope",scope).issueTime(new Date()).expirationTime(Date.from(Instant.now().plusSeconds(120))).build());j.sign(new RSASSASigner((RSAPrivateKey)rsa.getPrivate()));return j.serialize();}
 private static HttpResponse<String> actorCall(HttpClient h,String base,KeyPair rsa,KeyPair ec,String issuer,String method,String path,String scope,String role,String body,String key,String match,UUID party)throws Exception{UUID corr=UUID.randomUUID();byte[] bytes=body.getBytes(StandardCharsets.UTF_8);var actor=new ActorAssertion.Actor(party,issuer,"synthetic-user",null,Set.of(role),Set.of(scope),null);var binding=new ActorAssertion.Binding("experience",scope,method,path,corr,ActorAssertion.Binding.bodyHash(bytes));var jwt=new SignedJWT(new JWSHeader.Builder(JWSAlgorithm.ES256).keyID("active").type(new JOSEObjectType("nigson-actor+jwt")).build(),ActorAssertion.claims(actor,binding,Instant.now()));jwt.sign(new ECDSASigner((ECPrivateKey)ec.getPrivate()));var b=HttpRequest.newBuilder(URI.create(base+path)).timeout(Duration.ofSeconds(10)).header("Authorization","Bearer "+workload(rsa,issuer,"nigson-commerce",scope)).header("X-Nigson-Actor",jwt.serialize()).header("X-Correlation-ID",corr.toString()).header("Accept","application/json");if(key!=null)b.header("Idempotency-Key",key);if(match!=null)b.header("If-Match",match);if(!method.equals("GET"))b.header("Content-Type","application/json");return h.send(b.method(method,body.isEmpty()?HttpRequest.BodyPublishers.noBody():HttpRequest.BodyPublishers.ofString(body)).build(),HttpResponse.BodyHandlers.ofString());}
 private static HttpResponse<String> privateCall(HttpClient h,String url,String method,String body,String bearer,String key,String match)throws Exception{UUID corr=UUID.randomUUID();var b=HttpRequest.newBuilder(URI.create(url)).timeout(Duration.ofSeconds(10)).header("Authorization","Bearer "+bearer).header("X-Correlation-ID",corr.toString()).header("Accept","application/json").header("Content-Type","application/json").header("Idempotency-Key",key).header("If-Match",match);return h.send(b.method(method,HttpRequest.BodyPublishers.ofString(body)).build(),HttpResponse.BodyHandlers.ofString());}
}
